public class FileCopierTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) throws Exception {
        java.nio.file.Path dir = java.nio.file.Files.createTempDirectory("copier");
        java.nio.file.Path from = dir.resolve("source.bin");
        java.nio.file.Path to = dir.resolve("target.bin");
        java.nio.file.Path emptySrc = dir.resolve("empty.txt");
        java.nio.file.Path emptyDst = dir.resolve("empty-copy.txt");
        try {
            byte[] data = new byte[300];
            for (int i = 0; i < data.length; i++) {
                data[i] = (byte) (i * 7);
            }
            java.nio.file.Files.write(from, data);
            java.nio.file.Files.write(emptySrc, new byte[0]);
            try {
                FileCopier.copy(from, to);
                check("target exists after copy", true, java.nio.file.Files.exists(to));
                check("all 300 bytes identical", true,
                        java.nio.file.Files.exists(to) && java.util.Arrays.equals(
                                data, java.nio.file.Files.readAllBytes(to)));
                check("target size", 300L,
                        java.nio.file.Files.exists(to)
                                ? java.nio.file.Files.size(to) : -1L);
                check("source left intact", true,
                        java.util.Arrays.equals(data, java.nio.file.Files.readAllBytes(from)));
                FileCopier.copy(emptySrc, emptyDst);
                check("empty file copy exists", true, java.nio.file.Files.exists(emptyDst));
                check("empty file copy is empty", 0L,
                        java.nio.file.Files.exists(emptyDst)
                                ? java.nio.file.Files.size(emptyDst) : -1L);
            } catch (Exception e) {
                check("no unexpected exception", "none", e.getClass().getSimpleName());
            }
        } finally {
            java.nio.file.Files.deleteIfExists(from);
            java.nio.file.Files.deleteIfExists(to);
            java.nio.file.Files.deleteIfExists(emptySrc);
            java.nio.file.Files.deleteIfExists(emptyDst);
            java.nio.file.Files.deleteIfExists(dir);
        }
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

